import { cleanup, fireEvent, render, screen, within } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'
import type { ActionContext } from '../../../data/action_context'
import type { AgentConversation } from '../../../data/data_types'
import { ActionConversationPicker } from './action_conversation_picker'
import { conversationOptions } from './action_conversation_store'
import { conversationPickerLabel, formatConversationDateTime } from './action_conversation_picker_data'

function conversation(overrides: Partial<AgentConversation> = {}): AgentConversation {
    return {
        actionId: 'action-review',
        cardInternalId: 'card-1',
        cardPath: 'design/F-1.md',
        completedAt: '2026-07-15T10:01:00.000Z',
        entries: [],
        hasExplicitTitle: true,
        id: 'conversation-1',
        path: 'design/activity/card__card-1.json#conversation=conversation-1',
        providerSessions: [],
        startedAt: '2026-07-15T10:00:00.000Z',
        status: 'completed',
        title: 'Review',
        viewed: true,
        ...overrides,
    }
}

describe('conversation picker data', () => {
    afterEach(cleanup)

    it('allows selecting empty conversation after history is selected', () => {
        const onChange = vi.fn()
        const selectedConversation = conversation()
        render(
            <ActionConversationPicker
                conversations={[selectedConversation]}
                disabled={false}
                loading={false}
                onChange={onChange}
                selectedPath={selectedConversation.path}
            />,
        )

        fireEvent.mouseDown(screen.getByRole('combobox', { name: 'Conversation history' }))
        const options = within(screen.getByRole('listbox'))
        const emptyConversation = options.getByRole('option', { name: 'Conversations' })
        expect(emptyConversation).not.toHaveAttribute('aria-disabled', 'true')
        fireEvent.click(emptyConversation)

        expect(onChange).toHaveBeenCalledOnce()
    })

    it('uses explicit titles with local date/time and falls back to date/time alone', () => {
        const titled = conversation()
        const untitled = conversation({ hasExplicitTitle: false, title: 'conversation-1' })

        expect(conversationPickerLabel(titled)).toBe(`Review â€” ${formatConversationDateTime(titled.startedAt)}`)
        expect(conversationPickerLabel(untitled)).toBe(formatConversationDateTime(untitled.startedAt))
        expect(formatConversationDateTime('invalid timestamp')).toBe('invalid timestamp')
    })

    it('filters context, sorts newest first, and replaces live duplicates', () => {
        const context: ActionContext = { cardInternalId: 'card-1', file: 'design/F-1.md', kind: 'card' }
        const older = conversation({ id: 'older', path: 'older.json', startedAt: '2026-07-14T10:00:00.000Z' })
        const newest = conversation({ id: 'newest', path: 'newest.json', startedAt: '2026-07-15T10:00:00.000Z' })
        const otherAction = conversation({ actionId: 'action-implement', id: 'other-action', path: 'other-action.json' })
        const otherCard = conversation({ cardInternalId: 'card-2', cardPath: 'design/F-2.md', id: 'other', path: 'other.json' })
        const liveNewest = conversation({ entries: [{ content: 'live', id: 'm1', kind: 'message', role: 'assistant', timestamp: 'now' }], id: 'newest', path: 'live-newest.json' })

        const result = conversationOptions([older, newest, otherAction, otherCard], 'action-review', context, liveNewest)

        expect(result.map(({ id }) => id)).toEqual(['newest', 'older'])
        expect(result[0].entries[0].content).toBe('live')
    })

    it('keeps project conversations separate from card conversations', () => {
        const projectConversation = conversation({ cardInternalId: null, cardPath: null, id: 'project', path: 'project.json' })

        expect(conversationOptions([conversation(), projectConversation], 'action-review', { kind: 'project' }, null))
            .toEqual([projectConversation])
    })
})

import { useId, useMemo, useState } from 'react'
import { displayActionsForContext, projectContextWithWorktree, type ActionContext } from '../../../../data/action_context'
import { dataService } from '../../../../services/data/data_service'
import { actionRunRegistry } from '../../../../services/actions/action_run_registry'
import { cardAgentState } from '../../../../services/agents/card_agent_state'
import { isReleasedCardActionContext, RELEASED_CARD_RUN_MESSAGE } from '../../../../../../shared/released_card_actions.mjs'
import { useActions } from '../../../hooks/use_actions'
import { useProjectState } from '../../../hooks/use_project_state'
import { useProjectActionWorktree } from '../../../hooks/use_worktrees'
import { ActionPopupContent } from './action_popup_content'
import { resolveInitialActionId, type PersistedActionStates } from './action_popup_initial_action'

export { CARD_RUN_POPUP_SIZE_STORAGE_KEY, PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY } from './action_popup_content'

function resolvePopupTarget(context: ActionContext, snapshot: ReturnType<typeof useProjectState>['snapshot']) {
    if (context.kind === 'project') return 'Project'
    if (context.kind !== 'card') return null

    const cards = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]

    return cards.find(({ header }) => header.internalId === context.cardInternalId)?.header.id ?? null
}

function resolveCardInternalId(context: ActionContext, snapshot: ReturnType<typeof useProjectState>['snapshot']) {
    const cards = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]
    const card = context.cardInternalId
        ? cards.find(({ header }) => header.internalId === context.cardInternalId)
        : cards.find(({ path }) => path === context.file)

    return card?.header.internalId ?? context.cardInternalId ?? null
}

function persistedActionStates(
    actions: ReturnType<typeof displayActionsForContext>,
    context: ActionContext,
    snapshot: ReturnType<typeof useProjectState>['snapshot'],
) {
    const cardInternalId = resolveCardInternalId(context, snapshot)
    if (!cardInternalId) return {}

    const conversations = dataService.agents.getAgentConversations(cardInternalId)

    return Object.fromEntries(actions.map(({ id }) => [
        id,
        cardAgentState(conversations.filter((conversation) => conversation.actionId === id)),
    ])) as PersistedActionStates
}

interface ActionPopupProps {
    anchorElement: HTMLElement | null
    context: ActionContext
    draggable?: boolean
    initialActionId?: string
    onActivate?: () => void
    onClose: () => void
    open?: boolean
    popupEntryId?: string
    stackPosition?: number
}

/** Universal action selector and run popup for the supplied context. */
export function ActionPopup(props: ActionPopupProps) {
    const { anchorElement, context, initialActionId, open } = props
    const { actions: loadedActions } = useActions()
    const { project, snapshot } = useProjectState()
    const projectActionWorktree = useProjectActionWorktree()
    const effectiveContext = useMemo(
        () => projectContextWithWorktree(context, projectActionWorktree),
        [context, projectActionWorktree],
    )
    const actions = useMemo(() => displayActionsForContext(loadedActions, effectiveContext), [effectiveContext, loadedActions])
    const [selectedActionId, setSelectedActionId] = useState<string | null>(() => resolveInitialActionId(
        actions,
        initialActionId,
        actionRunRegistry.getContextActiveSnapshot(effectiveContext),
        persistedActionStates(actions, effectiveContext, snapshot),
    ))
    const [fullHeight, setFullHeight] = useState(false)
    const titleId = useId()
    // A run that edits its own card changes the context (state, title, worktree), so the
    // selected action can drop out of the filtered list mid-run. Keep it selectable instead
    // of closing the popup or silently switching to another action.
    const retainedAction = selectedActionId ? loadedActions.find(({ id }) => id === selectedActionId) ?? null : null
    const selectedAction = actions.find(({ id }) => id === selectedActionId) ?? retainedAction ?? actions[0] ?? null
    const selectableActions = selectedAction && !actions.some(({ id }) => id === selectedAction.id)
        ? [...actions, selectedAction]
        : actions
    const target = resolvePopupTarget(context, snapshot)
    const releasesFolder = dataService.getConfig()?.releasesFolder
    const readOnlyMessage = releasesFolder && isReleasedCardActionContext(effectiveContext, releasesFolder)
        ? RELEASED_CARD_RUN_MESSAGE
        : null

    const handleSelectAction = (actionId: string) => {
        setSelectedActionId(actionId)
    }

    const handleToggleFullHeight = () => setFullHeight((current) => !current)

    if (!selectedAction) return null

    return (
        <ActionPopupContent
            {...props}
            action={selectedAction}
            actions={selectableActions}
            assignmentContext={effectiveContext}
            baseContext={context}
            fullHeight={fullHeight}
            onSelectAction={handleSelectAction}
            onToggleFullHeight={handleToggleFullHeight}
            open={open ?? !!anchorElement}
            primaryPath={project?.rootPath ?? project?.id ?? null}
            readOnlyMessage={readOnlyMessage}
            target={target}
            titleId={titleId}
        />
    )
}

import { useEffect, useMemo, useSyncExternalStore, type ChangeEvent } from 'react'
import type { ActionContext } from '../../../data/action_context'
import type { ActionRun } from '../../../services/actions/action_run_registry'
import { useActionRunSelector } from '../../hooks/use_action_runs'
import { useCardActionUnseenResults } from '../../hooks/use_card_action_unseen_results'
import { ActionConversationPicker } from './action_conversation_picker'
import type { ConversationPickerConversation } from './action_conversation_picker_data'
import type { ActionConversationStore } from './action_conversation_store'

interface ActionConversationPickerOwnerProps {
    actionId: string
    context: ActionContext
    store: ActionConversationStore
}

function selectSessionActive(run: ActionRun | null) {
    return run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput'
}

/** Loads and selects conversation history at picker boundary. */
export function ActionConversationPickerOwner(props: ActionConversationPickerOwnerProps) {
    const { actionId, context, store } = props
    const sessionActive = useActionRunSelector(actionId, context, selectSessionActive)
    const liveActionId = useActionRunSelector(actionId, context, (run) => run?.conversation?.actionId)
    const liveCardInternalId = useActionRunSelector(actionId, context, (run) => run?.conversation?.cardInternalId)
    const liveHasExplicitTitle = useActionRunSelector(actionId, context, (run) => run?.conversation?.hasExplicitTitle)
    const liveId = useActionRunSelector(actionId, context, (run) => run?.conversation?.id ?? null)
    const livePath = useActionRunSelector(actionId, context, (run) => run?.conversation?.path)
    const liveStartedAt = useActionRunSelector(actionId, context, (run) => run?.conversation?.startedAt)
    const liveTitle = useActionRunSelector(actionId, context, (run) => run?.conversation?.title)
    const unseenResultConversations = useCardActionUnseenResults([actionId], context)
    const snapshot = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
    store.configureInitialSelection(unseenResultConversations[0]?.path ?? null)
    const liveConversation = useMemo<ConversationPickerConversation | null>(() => {
        if (liveId === null) return null
        if (liveHasExplicitTitle === undefined || livePath === undefined || liveStartedAt === undefined || liveTitle === undefined) {
            throw new Error('Live conversation is missing picker metadata')
        }

        return {
            actionId: liveActionId,
            cardInternalId: liveCardInternalId,
            hasExplicitTitle: liveHasExplicitTitle,
            id: liveId,
            path: livePath,
            startedAt: liveStartedAt,
            title: liveTitle,
        }
    }, [liveActionId, liveCardInternalId, liveHasExplicitTitle, liveId, livePath, liveStartedAt, liveTitle])

    useEffect(() => {
        void store.load()
    }, [store])

    const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
        void store.select(event.target.value)
    }

    return (
        <ActionConversationPicker
            conversations={store.conversationOptions(liveConversation)}
            disabled={sessionActive}
            loading={snapshot.loading}
            onChange={handleChange}
            selectedPath={liveConversation?.path ?? snapshot.selectedConversation?.path ?? ''}
        />
    )
}

import { MenuItem, TextField } from '@mui/material'
import type { ChangeEvent } from 'react'
import { conversationPickerLabel, type ConversationPickerConversation } from './action_conversation_picker_data'

interface ActionConversationPickerProps {
    conversations: ConversationPickerConversation[]
    disabled: boolean
    loading: boolean
    onChange: (event: ChangeEvent<HTMLInputElement>) => void
    selectedPath: string
}

/** Selects one persisted conversation for popup display and continuation. */
export function ActionConversationPicker(props: ActionConversationPickerProps) {
    const { conversations, disabled, loading, onChange, selectedPath } = props
    const hasConversations = conversations.length > 0

    return (
        <TextField
            disabled={disabled || loading || !hasConversations}
            onChange={onChange}
            select
            slotProps={{ select: { displayEmpty: true, inputProps: { 'aria-label': 'Conversation history' } } }}
            sx={{
                minWidth: 150,
                '& .MuiInputBase-root': { borderRadius: 0.75, color: 'text.secondary', fontSize: 12, fontWeight: 600, height: 26, pl: 0.75 },
                '& .MuiInputBase-root:hover': { bgcolor: 'action.hover', color: 'text.primary' },
                '& .MuiInput-root:before, & .MuiInput-root:after': { display: 'none' },
            }}
            value={selectedPath}
            variant="standard"
        >
            <MenuItem value="">Conversations</MenuItem>
            {conversations.map((conversation) => (
                <MenuItem key={conversation.path} value={conversation.path}>{conversationPickerLabel(conversation)}</MenuItem>
            ))}
        </TextField>
    )
}

import type { AgentConversation } from '../../../data/data_types'

export type ConversationPickerConversation = Pick<
    AgentConversation,
    'actionId' | 'cardInternalId' | 'hasExplicitTitle' | 'id' | 'path' | 'startedAt' | 'title'
>

export function formatConversationDateTime(startedAt: string) {
    const date = new Date(startedAt)
    if (Number.isNaN(date.getTime())) return startedAt

    return date.toLocaleString(undefined, { dateStyle: 'short', timeStyle: 'short' })
}

export function conversationPickerLabel(conversation: ConversationPickerConversation) {
    const dateTime = formatConversationDateTime(conversation.startedAt)

    return conversation.hasExplicitTitle ? `${conversation.title} â€” ${dateTime}` : dateTime
}

import { useMemo } from 'react'
import { actionContextIdentity } from '../../../../data/action_context'
import {
    actionRunSettingsService,
    createSessionActionRunSettingsStore,
} from '../../../../services/actions/action_run_settings_service'
import { AgentAction } from './agent_action'
import { ActionPopupFrame } from './action_popup_frame'
import { CommandAction } from './command_action'
import { createActionPopupBindings, worktreeValidationMessage } from './action_popup_runtime'
import type { ActionPopupContentProps, ActionPopupRuntime } from './action_popup_types'

export { CARD_RUN_POPUP_SIZE_STORAGE_KEY, PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY } from './action_popup_frame'

/** Selects the action-specific popup content while preserving its runtime for the selected action. */
export function ActionPopupContent(props: ActionPopupContentProps) {
    const { action, assignmentContext } = props
    const settingsContextIdentity = actionContextIdentity(assignmentContext)
    const settingsStore = useMemo(
        () => assignmentContext.cardInternalId
            ? actionRunSettingsService.getCardStore(assignmentContext.cardInternalId, action.id)
            : createSessionActionRunSettingsStore(action.id, settingsContextIdentity),
        [action.id, assignmentContext.cardInternalId, settingsContextIdentity],
    )
    const bindings = useMemo(
        () => createActionPopupBindings(action, assignmentContext),
        [action, assignmentContext],
    )
    const runtime: ActionPopupRuntime = {
        ...bindings,
        runValidationError: worktreeValidationMessage(action, assignmentContext),
        settingsStore,
    }

    return (
        <ActionPopupFrame contentProps={props} conversationStore={bindings.conversationStore}>
            {action.type === 'agent'
                ? (
                    <AgentAction
                        action={action}
                        assignmentContext={assignmentContext}
                        baseContext={props.baseContext}
                        popupEntryId={props.popupEntryId}
                        readOnlyMessage={props.readOnlyMessage}
                        runtime={runtime}
                    />
                ) : (
                    <CommandAction
                        action={action}
                        assignmentContext={assignmentContext}
                        baseContext={props.baseContext}
                        readOnlyMessage={props.readOnlyMessage}
                        runtime={runtime}
                    />
                )}
        </ActionPopupFrame>
    )
}

import type { ActionContext } from '../../../data/action_context'
import type { AgentConversation } from '../../../data/data_types'
import { actionPromptDraftService } from '../../../services/actions/action_prompt_draft_service'
import { actionRunRegistry } from '../../../services/actions/action_run_registry'
import { dialogService } from '../../../services/dialog_service'
import type { ConversationPickerConversation } from './action_conversation_picker_data'
import { defaultLoadConversation, defaultLoadConversations } from '../run/popup/action_popup_defaults'

interface ActionConversationSnapshot {
    conversations: AgentConversation[]
    loading: boolean
    selectedConversation: AgentConversation | null
}

type Listener = () => void

function belongsToContext(conversation: ConversationPickerConversation, context: ActionContext) {
    return context.kind === 'project' || context.kind === 'merge-conflict'
        ? conversation.cardInternalId === null
        : conversation.cardInternalId === context.cardInternalId
}

function conversationTimestamp(conversation: ConversationPickerConversation) {
    const timestamp = Date.parse(conversation.startedAt)

    return Number.isNaN(timestamp) ? 0 : timestamp
}

export function conversationOptions<T extends ConversationPickerConversation>(
    conversations: T[],
    actionId: string,
    context: ActionContext,
    liveConversation: T | null,
) {
    const byId = new Map<string, T>()
    for (const conversation of conversations) {
        if (belongsToContext(conversation, context) && conversation.actionId === actionId) {
            byId.set(conversation.id, conversation)
        }
    }
    if (liveConversation && belongsToContext(liveConversation, context) && liveConversation.actionId === actionId) {
        byId.set(liveConversation.id, liveConversation)
    }

    return [...byId.values()].sort((left, right) => conversationTimestamp(right) - conversationTimestamp(left))
}

function latestWaitingConversation(conversations: AgentConversation[], actionId: string, context: ActionContext) {
    return conversations
        .filter((conversation) => belongsToContext(conversation, context)
            && conversation.actionId === actionId
            && conversation.status === 'waitingForInput')
        .sort((left, right) => conversationTimestamp(right) - conversationTimestamp(left))[0] ?? null
}

